package com.dlxyuki.wms.pickingbol;
import static org.assertj.core.api.Assertions.assertThat;import java.io.ByteArrayInputStream;import java.util.*;import org.apache.poi.ss.usermodel.CellType;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.junit.jupiter.api.Test;import org.springframework.web.bind.annotation.*;
class BolReadContractTest{@Test void routesAndWorkbookContract()throws Exception{assertThat(BolController.class.getAnnotation(RequestMapping.class).value()).containsExactly("/api/v1/bols");assertThat(BolController.class.getDeclaredMethod("export",long.class,com.dlxyuki.wms.user.UserAccount.class).getAnnotation(GetMapping.class).value()).containsExactly("/{bolId}/xlsx");Map<String,Object>b=Map.of("bol_no","BOL1");Map<String,Object>i=new LinkedHashMap<>();i.put("ob_no","OB1");i.put("ship_from_address","From");i.put("ship_to_address",null);i.put("amazon_fc_code","LAX9");i.put("container_number","C1");i.put("pallet_qty","12.50");i.put("carton_qty","20");i.put("weight_lbs","100.25");i.put("cbm","2.5");try(var w=new XSSFWorkbook(new ByteArrayInputStream(PickingBolService.bolWorkbook(b,List.of(i))))){var s=w.getSheet("BOL");assertThat(PickingBolService.BOL_HEADERS).hasSize(10);for(int x=0;x<10;x++)assertThat(s.getRow(0).getCell(x).getStringCellValue()).isEqualTo(PickingBolService.BOL_HEADERS.get(x));assertThat(s.getRow(1).getCell(6).getCellType()).isEqualTo(CellType.STRING);assertThat(s.getRow(1).getCell(6).getStringCellValue()).isEqualTo("12.50");}}}
